# Prime factorization of 75 and 5625
def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

print(f"Factors of 75: {prime_factorization(75)}")
print(f"Factors of 5625: {prime_factorization(5625)}")

